import{_ as e,o as t,c as s,a5 as r}from"./chunks/framework.a5no_H3L.js";const k=JSON.parse('{"title":"ASP.NET Core：跨平台 Web 框架","description":"本页回答三个问题：ASP.NET Core 是什么，它与旧的 ASP.NET 有何不同，什么场景适合用它。语言机制见认识 .NET 与 C#。","frontmatter":{"type":"explanation","level":"basic"},"headers":[],"relativePath":"csharp/04-aspnet-core/chapter-01-why-aspnet-core.md","filePath":"csharp/04-aspnet-core/chapter-01-why-aspnet-core.md"}'),i={name:"csharp/04-aspnet-core/chapter-01-why-aspnet-core.md"};function c(p,a,n,l,h,d){return t(),s("div",null,[...a[0]||(a[0]=[r(`<h1 id="asp-net-core-跨平台-web-框架" tabindex="-1" data-src-line="2" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md">ASP.NET Core：跨平台 Web 框架 <a class="header-anchor" href="#asp-net-core-跨平台-web-框架" aria-label="Permalink to &quot;ASP.NET Core：跨平台 Web 框架&quot;">​</a></h1><p data-src-line="4" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md">本页回答三个问题：ASP.NET Core 是什么，它与旧的 ASP.NET 有何不同，什么场景适合用它。语言机制见<a href="./../01-csharp-language/chapter-01-why-csharp.html">认识 .NET 与 C#</a>。</p><h2 id="_1-asp-net-core-是什么" tabindex="-1" data-src-line="6" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md">1. ASP.NET Core 是什么 <a class="header-anchor" href="#_1-asp-net-core-是什么" aria-label="Permalink to &quot;1. ASP.NET Core 是什么&quot;">​</a></h2><p data-src-line="8" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md">ASP.NET Core 是 .NET 上构建 Web 应用和 API 的跨平台框架。它运行在 .NET 运行时之上，提供 HTTP 服务器、请求处理管道、路由、依赖注入等基础设施：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP 请求 → Kestrel（HTTP 服务器）→ 中间件管道 → 路由 → 业务处理 → 响应</span></span></code></pre></div><p data-src-line="14" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md">它既服务 API（返回 JSON），也支持服务端渲染（Razor Pages / MVC 视图）、实时通信（SignalR）和 gRPC。</p><h2 id="_2-与旧-asp-net-的区别" tabindex="-1" data-src-line="16" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md">2. 与旧 ASP.NET 的区别 <a class="header-anchor" href="#_2-与旧-asp-net-的区别" aria-label="Permalink to &quot;2. 与旧 ASP.NET 的区别&quot;">​</a></h2><p data-src-line="18" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md">ASP.NET Core 是 2016 年推出的重写版本，与运行在 .NET Framework 上的旧 ASP.NET 有本质区别：</p><table tabindex="0"><thead data-src-line="20" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md"><tr data-src-line="20" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md"><th style="text-align:left;"></th><th style="text-align:left;">旧 ASP.NET</th><th style="text-align:left;">ASP.NET Core</th></tr></thead><tbody data-src-line="22" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md"><tr data-src-line="22" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md"><td style="text-align:left;">运行时</td><td style="text-align:left;">仅 Windows，.NET Framework</td><td style="text-align:left;">跨平台，.NET</td></tr><tr data-src-line="23" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md"><td style="text-align:left;">模块化</td><td style="text-align:left;">依赖整机 IIS</td><td style="text-align:left;">自包含、可独立部署</td></tr><tr data-src-line="24" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md"><td style="text-align:left;">性能</td><td style="text-align:left;">一般</td><td style="text-align:left;">显著更高（Kestrel + 异步）</td></tr><tr data-src-line="25" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md"><td style="text-align:left;">配置</td><td style="text-align:left;">web.config 为主</td><td style="text-align:left;">appsettings + 环境变量等</td></tr></tbody></table><p data-src-line="27" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md">旧 ASP.NET（含 Web Forms）已进入维护，新项目应使用 ASP.NET Core。</p><h2 id="_3-何时用-asp-net-core" tabindex="-1" data-src-line="29" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md">3. 何时用 ASP.NET Core <a class="header-anchor" href="#_3-何时用-asp-net-core" aria-label="Permalink to &quot;3. 何时用 ASP.NET Core&quot;">​</a></h2><ul data-src-line="31" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md"><li data-src-line="31" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md"><strong>Web API</strong>：为前后端分离的 Web/移动应用提供 JSON 接口。</li><li data-src-line="32" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md"><strong>微服务</strong>：轻量、可独立部署、跨平台。</li><li data-src-line="33" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md"><strong>服务端渲染</strong>：Razor Pages / MVC 生成 HTML。</li><li data-src-line="34" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md"><strong>实时应用</strong>：SignalR 的 WebSocket 通信。</li></ul><p data-src-line="36" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md">它适合需要 HTTP 服务、且希望利用 .NET 生态（EF Core、依赖注入、异步）的场景。</p><h2 id="_4-一个最小应用" tabindex="-1" data-src-line="38" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md">4. 一个最小应用 <a class="header-anchor" href="#_4-一个最小应用" aria-label="Permalink to &quot;4. 一个最小应用&quot;">​</a></h2><p data-src-line="40" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md">创建 Web 应用后，<code>Program.cs</code> 是这样的结构：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> builder</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> WebApplication.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">CreateBuilder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(args);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> app</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> builder.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MapGet</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Hello, World!&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p data-src-line="51" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md"><code>WebApplication.CreateBuilder</code> 初始化配置、日志、依赖注入容器；<code>builder.Build()</code> 组装管道；<code>MapGet</code> 注册路由；<code>Run()</code> 启动监听。这就是 Minimal API 的骨架，详见<a href="./chapter-02-minimal-api.html">Minimal API</a>。</p><p data-src-line="53" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md">启动后访问根路径返回 <code>Hello, World!</code>。执行 <code>dotnet run</code> 会监听默认地址（如 <code>http://localhost:5000</code>），这是验证环境是否可用的最快方式。</p><h2 id="_5-与-spring-的对照" tabindex="-1" data-src-line="55" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md">5. 与 Spring 的对照 <a class="header-anchor" href="#_5-与-spring-的对照" aria-label="Permalink to &quot;5. 与 Spring 的对照&quot;">​</a></h2><p data-src-line="57" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md">熟悉 Spring 的读者可以这样对应：ASP.NET Core 的中间件管道对应 Spring 的过滤器/拦截器链；依赖注入容器对应 Spring IoC；<code>Program.cs</code> 的注册对应 <code>@Configuration</code>/<code>@Bean</code>；EF Core 对应 JPA/Hibernate。但 ASP.NET Core 更强调「约定 + 内置」而不是 XML/注解驱动的装配。</p><h2 id="_6-后续阅读" tabindex="-1" data-src-line="59" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md">6. 后续阅读 <a class="header-anchor" href="#_6-后续阅读" aria-label="Permalink to &quot;6. 后续阅读&quot;">​</a></h2><ul data-src-line="61" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md"><li data-src-line="61" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md"><a href="./chapter-02-minimal-api.html">Minimal API</a>解释最简的 API 写法。</li><li data-src-line="62" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md"><a href="./chapter-03-mvc-routing.html">路由与 MVC</a>解释控制器与路由。</li><li data-src-line="63" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md"><a href="./chapter-04-middleware-pipeline.html">中间件管道</a>解释请求如何流经各中间件。</li><li data-src-line="64" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md"><a href="./chapter-05-dependency-injection.html">依赖注入</a>解释服务的生命周期与注入。</li></ul><blockquote data-src-line="66" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md"><p data-src-line="66" data-src-file="csharp/04-aspnet-core/chapter-01-why-aspnet-core.md">本页的技术边界按 .NET 10 / C# 14 核对；ASP.NET Core 自 2016 年发布，跨平台自 1.0 起。官方参考：<a href="https://learn.microsoft.com/en-us/aspnet/core/" target="_blank" rel="noreferrer">ASP.NET Core 文档</a>。</p></blockquote>`,23)])])}const y=e(i,[["render",c]]);export{k as __pageData,y as default};
